package com.example.starter.damage.domain;

/**
 * 残损案流转状态：到港登记 → 检验 → 估价 → 修理批复 → 复检 → 放行/全损。
 * RELEASED 与 TOTAL_LOSS 为结案终态。
 */
public enum CaseStatus {
    /** 到港登记，待检验 */
    REGISTERED,
    /** 已检验（残损项已登记），待估价 */
    SURVEYED,
    /** 已估价，待修理批复或全损结案 */
    ESTIMATED,
    /** 修理已批复，批复有效期 7 个 UTC 自然日 */
    APPROVED,
    /** 复检不合格后返修中（仅允许一次） */
    REWORK,
    /** 修理（或返修）已完工，待复检 */
    REPAIR_DONE,
    /** 复检合格，待放行结案 */
    REPAIR_PASSED,
    /** 返修后复检仍不合格，转全损评估待结案 */
    TOTAL_LOSS_PENDING,
    /** 终态：修理放行，案件已关闭 */
    RELEASED,
    /** 终态：全损结案 */
    TOTAL_LOSS
}

package com.example.starter.damage.domain;

/**
 * 残损案当前唯一判定：修理与全损不得并发成立。
 */
public enum Determination {
    /** 修理（单项修理费不超过箱值 30%，恰 30% 按修理处理） */
    REPAIR,
    /** 全损（任一单项修理费超过箱值 30%，或返修后复检仍不合格） */
    TOTAL_LOSS
}

package com.example.starter.damage.domain;

/**
 * 残损责任方。
 */
public enum Responsibility {
    /** 箱东责任 */
    OWNER,
    /** 码头责任 */
    TERMINAL
}

package com.example.starter.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;

/**
 * 全局时钟配置：业务时间统一取 UTC，测试可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 系统 UTC 时钟。
     */
    @Bean
    public Clock businessClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.damage.api;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码与中文错误消息，由全局异常处理器统一输出。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, message);
    }
}

